/** Build a minimal LogFile with lines. */
function makeLogFile(path: string, lines: string[]): LogFile {
  return {
    path,
    lines: lines.map((content, i) => ({
      lineNumber: i + 1,
      content,
      level: 'info' as const,
    })) as LogLine[],
    errorCount: 0,
