/**
 * Creates a minimal BundleProfile sufficient for seed generation tests.
 * The seed generator does not deeply inspect profile fields, so this is safe.
 */
function makeMinimalProfile(): BundleProfile {
  return {
    manifest: {
      bundlePath: '',
      extractedPath: '',
      files: [],
