if (poolFinding.id.startsWith('finding:ai:')) {
  // AI is the sole survivor for this structural group.
  result.push(mergeComponentGroup([poolFinding, ...competingHypotheses]));
  handledPoolKeys.add(poolKey);
  continue;
}

// Heuristic findings are displaced by each competing hypothesis, but their
// absorbed evidence is retained on every surviving theory so Pass 2 cannot
// accidentally erase that context later.
for (const hyp of competingHypotheses) {
  result.push(mergeComponentGroup([hyp, poolFinding]));
}

